ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  businessCentralResponse: {
    "@odata.context": payload.businessCentralResponse."@odata.context",
    value: payload.businessCentralResponse.value map (item) -> {
      "@odata.etag": item."@odata.etag",
       // Transform the 'value' array by renaming 'Name' to 'Company Name'
      "Company Name": item.Name,
      City: item.City,
      Country_Region_Code: item.Country_Region_Code,
      E_Mail: item.E_Mail,
      Home_Page: item.Home_Page
    }
  }
}

%dw 2.0
output application/json skipNullOn="everywhere"

var inputData = payload.businessCentralResponse

---
{
    businessCentralResponse: {
        "@odata.context": inputData."@odata.context",
		"@odata.count": inputData."@odata.count",
        value: (inputData.value default []) map (user) -> {
            "@odata.etag": user["@odata.etag"],
            User_Security_ID: user.User_Security_ID,
            User_Name: user.User_Name,
            Full_Name: user.Full_Name,
            State: user.State,
            Expiry_Date: user.Expiry_Date,
            Contact_Email: user.Contact_Email,
            Authentication_Email: user.Authentication_Email,
            AuthenticationStatus: user.AuthenticationStatus,
            Microsoft365State: user.Microsoft365State,
            UsersPermissions:
                if (!isEmpty(user.UsersPermissions default []))
                [
                    {
                        Company: (user.UsersPermissions map $.Company) distinctBy $
                    }
                ]
                else null
        }
    }
}

%dw 2.0 output application/json skipNullOn="everywhere" import * from dw::core::Strings import substringAfter from dw::core::Strings import substringBefore from dw::core::Strings var system = vars.BC_system var environment = vars.BC_env var tenantGuid = vars.BC_tenantGuid var BusinessCentralResponse = vars.BusinessCentralResponse // Pre-encode the company name to handle '&' //var company = vars.BC_company replace "&" with "%26" var odataContext = BusinessCentralResponse.businessCentralResponse."@odata.context" var odataCount = BusinessCentralResponse.businessCentralResponse."@odata.count" var company = odataContext substringAfter "Company('" substringBefore "')" var request_endpoint = vars.request_endpoint var baseUrl = "https://" ++ p('http.get.exp-erp.host') ++ '/api/' ++ request_endpoint var nextLink = vars.nextLink default ""
// Logic to clean and transform the query parameters
var updatedLink = do { var modifiedParams = ((nextLink splitBy "?")[1] default "") --- modifiedParams
//1. Transform other keys replace /\$schemaversion=[^&]*&/ with "" replace /\$environment=[^&]*&/ with "" replace /\$company=.*?\$tenantguid=[^&]*&/ with "" replace /\&aid/ with "&bcaid"
// 2. Final OData cleanup replace /\$/ with "bc" }
var newBaseUrl = baseUrl ++ '?' ++ "%24system=" ++ system ++ '&' ++ "%24companyBusinessCentral=" ++ company ++ '&' ++ "%24environmentBusinessCentral=" ++ environment ++ '&'++ "%24tenantGuidBusinessCentral=" ++ tenantGuid ++ '&' ++ updatedLink
--- {
"@odata.context": odataContext, "@odata.count": odataCount, "value": BusinessCentralResponse.businessCentralResponse.value, "@odata.nextLink": trim(newBaseUrl) }
